import React, { useState, useEffect } from 'react';
import Skeleton from './Skeleton';

const ImageWithSkeleton = ({ src, alt, className, width, height, loadingTime }) => {
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    const img = new Image();
    img.src = src;
    img.onload = () => {
      setTimeout(() => {
        setLoaded(true);
      }, loadingTime); // Utilise le paramètre loadingTime pour simuler le temps de chargement
    };
  }, [src, loadingTime]);

  return (
    <>
      {!loaded && <Skeleton width={width} height={height} />}
      <img
        src={src}
        alt={alt}
        className={className}
        style={{ display: loaded ? 'block' : 'none' }}
      />
    </>
  );
};

export default ImageWithSkeleton;
