import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import {
  FaHome,
  FaUser,
  FaProjectDiagram,
  FaBlog,
  FaEnvelope,
  FaStar,
  FaTools,
  FaGlobe,
  FaGamepad,
} from 'react-icons/fa';
import { useTranslation } from 'react-i18next';
import { motion, AnimatePresence } from 'framer-motion';
import logo from '../assets/logombe.png';

const Navbar = () => {
  const [menuOpen, setMenuOpen] = useState(false);
  const { t, i18n } = useTranslation();
  const location = useLocation();

  const toggleMenu = () => {
    setMenuOpen(!menuOpen);
  };

  const changeLanguage = (lng) => {
    i18n.changeLanguage(lng);
  };

  useEffect(() => {
    setMenuOpen(false);
  }, [location]);

  useEffect(() => {
    changeLanguage('fr');
  }, []);

  const navLinks = [
    { to: '/', label: t('navbar.home'), icon: <FaHome /> },
    { to: '/about', label: t('navbar.about'), icon: <FaUser /> },
    { to: '/experience', label: t('navbar.experience'), icon: <FaTools /> },
    { to: '/projects', label: t('navbar.projects'), icon: <FaProjectDiagram /> },
    { to: '/testimonials', label: t('navbar.testimonials'), icon: <FaStar /> },
    { to: '/blog', label: t('navbar.blog'), icon: <FaBlog /> },
    { to: '/games', label: t('navbar.games'), icon: <FaGamepad /> },
    { to: '/contact', label: t('navbar.contact'), icon: <FaEnvelope /> },
  ];

  return (
    <nav className="fixed top-0 left-0 w-full z-50 bg-transparent backdrop-blur-md">
      <div className="container mx-auto px-6 py-4 flex justify-between items-center">
        <Link to="/" className="flex items-center">
          <motion.img
            src={logo}
            alt="Logo"
            className="w-16 h-16 ml-4 cursor-pointer"
            initial={{ scale: 1, rotate: 0 }}
            whileHover={{ scale: 1.5, rotate: 360 }}
            transition={{ duration: 0.6 }}
          />
        </Link>
        <div className="hidden md:flex items-center">
          {navLinks.map((link) => (
            <motion.div
              key={link.to}
              className="relative mx-2"
              whileHover={{ scale: 1.2 }}
            >
              <Link
                to={link.to}
                className={`transition duration-300 flex items-center ${
                  location.pathname === link.to
                    ? 'text-yellow-500 font-bold'
                    : 'text-white'
                } hover:text-yellow-500`}
              >
                {React.cloneElement(link.icon, {
                  className: 'text-3xl md:text-2xl lg:text-xl',
                })}
                {/* Masquer le label sur les écrans ≤ 13 pouces */}
                <span className="ml-2 hidden lg:inline">
                  {link.label}
                </span>
              </Link>
            </motion.div>
          ))}
          {/* Langue */}
          <div className="flex items-center space-x-2 ml-4">
            <FaGlobe className="text-white" />
            <select
              onChange={(e) => changeLanguage(e.target.value)}
              className="bg-transparent text-white border-none outline-none"
              defaultValue="fr"
            >
              <option value="en" className="text-black">
                EN
              </option>
              <option value="fr" className="text-black">
                FR
              </option>
              <option value="ar" className="text-black">
                AR
              </option>
            </select>
          </div>
        </div>
        <div className="md:hidden flex items-center">
          <button className="outline-none mobile-menu-button" onClick={toggleMenu}>
            <motion.div
              initial={{ rotate: 0 }}
              animate={{ rotate: menuOpen ? 90 : 0 }}
              transition={{ duration: 0.3 }}
            >
              {menuOpen ? (
                <svg
                  className="w-6 h-6 text-white"
                  fill="none"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path d="M6 18L18 6M6 6l12 12" />
                </svg>
              ) : (
                <svg
                  className="w-6 h-6 text-white"
                  fill="none"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path d="M4 6h16M4 12h16m-7 6h7" />
                </svg>
              )}
            </motion.div>
          </button>
        </div>
      </div>
      <AnimatePresence>
        {menuOpen && (
          <motion.div
            className="mobile-menu md:hidden"
            initial={{ height: 0 }}
            animate={{ height: 'auto' }}
            exit={{ height: 0 }}
            transition={{ duration: 0.3 }}
            style={{ overflow: 'hidden' }}
          >
            <ul className="bg-gray-900 bg-opacity-90">
              {navLinks.map((link) => (
                <li
                  key={link.to}
                  className={`${
                    location.pathname === link.to
                      ? 'bg-yellow-500 font-bold'
                      : ''
                  }`}
                >
                  <Link
                    to={link.to}
                    className="block text-sm px-2 py-4 text-white font-semibold flex items-center justify-center"
                  >
                    {React.cloneElement(link.icon, {
                      className: 'text-3xl',
                    })}
                  </Link>
                </li>
              ))}
              {/* Langue */}
              <li className="flex items-center px-2 py-4 justify-center">
                <FaGlobe className="text-white mr-2" />
                <select
                  onChange={(e) => changeLanguage(e.target.value)}
                  className="bg-transparent text-white border-none outline-none"
                  defaultValue="fr"
                >
                  <option value="en" className="text-black">
                    EN
                  </option>
                  <option value="fr" className="text-black">
                    FR
                  </option>
                  <option value="ar" className="text-black">
                    AR
                  </option>
                </select>
              </li>
            </ul>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  );
};

export default Navbar;
