import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { FiDownload, FiCheck } from 'react-icons/fi';
import pdfFile from '../assets/documents/Dossier_de_Competences_de_Mohammed_Benmoussa.pdf';

const About = () => {
  const { t } = useTranslation();
  const [downloaded, setDownloaded] = useState(false);

  useEffect(() => {
    const isDownloaded = localStorage.getItem('isDownloaded');
    if (isDownloaded === 'true') {
      setDownloaded(true);
    }
  }, []);

  const handleDownload = () => {
    if (!downloaded) {
      const link = document.createElement('a');
      link.href = pdfFile;
      link.download = 'Dossier_de_Competences_de_Mohammed_Benmoussa.pdf';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      setDownloaded(true);
      localStorage.setItem('isDownloaded', 'true');
    }
  };

  return (
    <div className="w-full min-h-screen flex flex-col items-center bg-gradient-to-b from-gray-900 to-gray-700 py-32 px-8">
      <div
        className="max-w-4xl w-full mx-auto bg-white bg-opacity-10 p-8 rounded-xl shadow-2xl backdrop-blur-lg"
        aria-label={t('about.title')}
      >
        <h1 className="text-4xl font-bold text-white mb-6 text-center">
          {t('about.title')}
        </h1>

        <div className="flex justify-center mb-8">
          <div
            className={`flex items-center justify-center w-16 h-16 rounded-full bg-white shadow-xl transition-transform duration-500 ${
              downloaded ? 'transform scale-110 bg-green-500 cursor-not-allowed' : 'hover:scale-125'
            }`}
            onClick={handleDownload}
          >
            {downloaded ? (
              <FiCheck className="text-white text-4xl animate-pulse" />
            ) : (
              <FiDownload className="text-blue-500 text-4xl animate-bounce" />
            )}
          </div>
        </div>

        <section className="mb-8" aria-labelledby="profil-professionnel">
          <h2 id="profil-professionnel" className="text-2xl font-semibold text-white mb-4">
            {t('about.professionalProfile.title')}
          </h2>
          <p className="text-gray-300 leading-relaxed">{t('about.professionalProfile.description')}</p>
        </section>

        <section className="mb-8" aria-labelledby="competences-techniques">
          <h2 id="competences-techniques" className="text-2xl font-semibold text-white mb-4">
            {t('about.technicalSkills.title')}
          </h2>
          <div className="text-gray-300 leading-relaxed">
            <h3 className="text-xl font-semibold text-white mb-2">
              {t('about.technicalSkills.frontEndDevelopment.title')}
            </h3>
            <ul className="list-disc pl-5">
            {t('about.technicalSkills.frontEndDevelopment.skills', { returnObjects: true }).map((skill, index) => (
  <li key={index}>{skill}</li>
))}
            </ul>

            <h3 className="text-xl font-semibold text-white mt-4 mb-2">
              {t('about.technicalSkills.backEndDevelopment.title')}
            </h3>
            <ul className="list-disc pl-5">
              {t('about.technicalSkills.backEndDevelopment.skills', { returnObjects: true }).map((skill, index) => (
                <li key={index}>{skill}</li>
              ))}
            </ul>

            <h3 className="text-xl font-semibold text-white mt-4 mb-2">
              {t('about.technicalSkills.developmentTools.title')}
            </h3>
            <ul className="list-disc pl-5">
              {t('about.technicalSkills.developmentTools.skills', { returnObjects: true }).map((skill, index) => (
                <li key={index}>{skill}</li>
              ))}
            </ul>

            <h3 className="text-xl font-semibold text-white mt-4 mb-2">
              {t('about.technicalSkills.databases.title')}
            </h3>
            <ul className="list-disc pl-5">
              {t('about.technicalSkills.databases.skills', { returnObjects: true }).map((skill, index) => (
                <li key={index}>{skill}</li>
              ))}
            </ul>

            <h3 className="text-xl font-semibold text-white mt-4 mb-2">
              {t('about.technicalSkills.otherSkills.title')}
            </h3>
            <ul className="list-disc pl-5">
              {t('about.technicalSkills.otherSkills.skills', { returnObjects: true }).map((skill, index) => (
                <li key={index}>{skill}</li>
              ))}
            </ul>
          </div>
        </section>

        <section className="mb-8" aria-labelledby="experiences-professionnelles">
          <h2 id="experiences-professionnelles" className="text-2xl font-semibold text-white mb-4">
            {t('about.relevantProfessionalExperiences.title')}
          </h2>
          <ol className="relative border-l border-gray-300">
            {t('about.relevantProfessionalExperiences.experiences', { returnObjects: true }).map((experience, index) => (
              <li key={index} className="mb-10 ml-6">
                <div className="absolute w-3 h-3 bg-blue-500 rounded-full -left-1.5"></div>
                <time className="mb-1 text-lg font-normal leading-none text-gray-400">{experience.date}</time>
                <h3 className="text-lg font-semibold text-white">{experience.position}</h3>
                <p className="text-base font-normal text-gray-400">{experience.description}</p>
              </li>
            ))}
          </ol>
        </section>

        <section className="mb-8" aria-labelledby="projets-academiques">
          <h2 id="projets-academiques" className="text-2xl font-semibold text-white mb-4">
            {t('about.academicProjects.title')}
          </h2>
          <ol className="relative border-l border-gray-300">
            {t('about.academicProjects.projects', { returnObjects: true }).map((project, index) => (
              <li key={index} className="mb-10 ml-6">
                <div className="absolute w-3 h-3 bg-green-500 rounded-full -left-1.5"></div>
                <time className="mb-1 text-lg font-normal leading-none text-gray-400">{project.date}</time>
                <h3 className="text-lg font-semibold text-white">{project.title}</h3>
                <p className="text-base font-normal text-gray-400">{project.description}</p>
              </li>
            ))}
          </ol>
        </section>

        <section className="mb-8" aria-labelledby="formations">
          <h2 id="formations" className="text-2xl font-semibold text-white mb-4">
            {t('about.education.title')}
          </h2>
          <ol className="relative border-l border-gray-300">
            {t('about.education.degrees', { returnObjects: true }).map((degree, index) => (
              <li key={index} className="mb-10 ml-6">
                <div className="absolute w-3 h-3 bg-yellow-500 rounded-full -left-1.5"></div>
                <time className="mb-1 text-lg font-normal leading-none text-gray-400">{degree.date}</time>
                <h3 className="text-lg font-semibold text-white">{degree.degree}</h3>
                <p className="text-base font-normal text-gray-400">{degree.option}</p>
              </li>
            ))}
          </ol>
        </section>

        <section className="mb-8" aria-labelledby="certifications">
          <h2 id="certifications" className="text-2xl font-semibold text-white mb-4">
            {t('about.certifications.title')}
          </h2>
          <ol className="relative border-l border-gray-300">
            {t('about.certifications.certificates', { returnObjects: true }).map((certificate, index) => (
              <li key={index} className="mb-10 ml-6">
                <div className="absolute w-3 h-3 bg-purple-500 rounded-full -left-1.5"></div>
                <time className="mb-1 text-lg font-normal leading-none text-gray-400">{certificate.date}</time>
                <h3 className="text-lg font-semibold text-white">{certificate.certificate}</h3>
                {certificate.certificate === 'TOEIC - ETS' ? (
                  <p className="text-base font-normal text-gray-400">
                    {certificate.description}
                    <a
                      href="https://www.etsglobal.org/fr/en/digital-score-report/77C369F820FD9A6FCD9092A2066DDED4B20692CDC3F7FA91F08F0D6D4137B457REhiWUhKM0pzaWhaWitpV09LS1ZtNmMvOWFSREozU1FySEhiNjFaZHZyU2ROd1JI"
                      className="text-blue-400 underline ml-2"
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      {t('about.certifications.toeicLink')}
                    </a>
                  </p>
                ) : certificate.certificate === 'Learn Android Application Development - Udemy' ? (
                  <p className="text-base font-normal text-gray-400">
                    <a
                      href="https://www.udemy.com/certificate/UC-M5VMTMMM/"
                      className="text-blue-400 underline"
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      {t('about.certifications.androidLink')}
                    </a>
                  </p>
                ) : certificate.certificate === 'Object Oriented Programming (OOPs) for JAVA - Udemy' ? (
                  <p className="text-base font-normal text-gray-400">
                    <a
                      href="https://www.udemy.com/certificate/UC-EZWWDGDG/"
                      className="text-blue-400 underline"
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      {t('about.certifications.javaLink')}
                    </a>
                  </p>
                ) : certificate.certificate === 'Crypto Currency - Udemy' ? (
                  <p className="text-base font-normal text-gray-400">
                    <a
                      href="https://www.udemy.com/certificate/UC-3c3cf87a-6b63-4118-a242-295f2435996a/"
                      className="text-blue-400 underline"
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      {t('about.certifications.cryptoLink')}
                    </a>
                  </p>
                ) : (
                  <p className="text-base font-normal text-gray-400">{certificate.description}</p>
                )}
              </li>
            ))}
          </ol>
        </section>

        <section aria-labelledby="conclusion">
          <h2 id="conclusion" className="text-2xl font-semibold text-white mb-4">
            {t('about.conclusion.title')}
          </h2>
          <p className="text-gray-300 leading-relaxed">{t('about.conclusion.description')}</p>
        </section>
      </div>
    </div>
  );
};

export default About;
