import React, { useState, useEffect, useRef } from 'react';
import {
  FaPlay,
  FaPause,
  FaRedo,
  FaForward,
  FaTrophy,
  FaArrowUp,
  FaArrowDown,
  FaArrowLeft,
  FaArrowRight,
  FaRegCircle,
} from 'react-icons/fa';
import { Howl } from 'howler';

const SnakeGame = () => {
  const [snake, setSnake] = useState([{ x: 10, y: 10 }]);
  const [direction, setDirection] = useState({ x: 0, y: -1 });
  const [food, setFood] = useState({ x: 5, y: 5 });
  const [gameOver, setGameOver] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [score, setScore] = useState(0);
  const [highScore, setHighScore] = useState(
    parseInt(localStorage.getItem('highScore')) || 0
  );

  const boardRef = useRef(null);
  const gridSize = 20;
  const tileSize = 20;

  // Sons
  const eatSound = useRef(
    new Howl({ src: ['eat.mp3'], volume: 0.5 })
  ).current;
  const gameOverSound = useRef(
    new Howl({ src: ['gameover.mp3'], volume: 0.5 })
  ).current;

  const handleKeyDown = (e) => {
    if (isPlaying) {
      switch (e.key) {
        case 'ArrowUp':
          e.preventDefault();
          if (direction.y !== 1) setDirection({ x: 0, y: -1 });
          break;
        case 'ArrowDown':
          e.preventDefault();
          if (direction.y !== -1) setDirection({ x: 0, y: 1 });
          break;
        case 'ArrowLeft':
          e.preventDefault();
          if (direction.x !== 1) setDirection({ x: -1, y: 0 });
          break;
        case 'ArrowRight':
          e.preventDefault();
          if (direction.x !== -1) setDirection({ x: 1, y: 0 });
          break;
        default:
          break;
      }
    }
  };

  const handleDirectionChange = (newDirection) => {
    if (!isPlaying) return;
    // Empêcher le serpent de faire demi-tour
    if (
      (newDirection.x === -direction.x && direction.x !== 0) ||
      (newDirection.y === -direction.y && direction.y !== 0)
    ) {
      return;
    }
    setDirection(newDirection);
  };

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isPlaying, direction]);

  useEffect(() => {
    const moveSnake = () => {
      setSnake((prevSnake) => {
        const newSnake = [...prevSnake];
        const head = {
          x: newSnake[0].x + direction.x,
          y: newSnake[0].y + direction.y,
        };

        // Vérifier les collisions
        if (isCollision(head, newSnake)) {
          setGameOver(true);
          setIsPlaying(false);
          gameOverSound.play();
          if (score > highScore) {
            setHighScore(score);
            localStorage.setItem('highScore', score);
          }
          return prevSnake;
        }

        newSnake.unshift(head);

        if (head.x === food.x && head.y === food.y) {
          setFood(generateFoodPosition(newSnake));
          setScore((prevScore) => prevScore + 1);
          eatSound.play();
        } else {
          newSnake.pop();
        }

        return newSnake;
      });
    };

    if (isPlaying && !gameOver) {
      const interval = setInterval(moveSnake, 150);
      return () => clearInterval(interval);
    }
  }, [direction, food, isPlaying, gameOver]);

  const isCollision = (head, snakeBody) => {
    // Vérifier les collisions avec les murs
    if (
      head.x < 0 ||
      head.x >= gridSize ||
      head.y < 0 ||
      head.y >= gridSize
    ) {
      return true;
    }
    // Vérifier les collisions avec le corps du serpent
    for (let segment of snakeBody) {
      if (head.x === segment.x && head.y === segment.y) {
        return true;
      }
    }
    return false;
  };

  const generateFoodPosition = (snakeBody) => {
    let newFoodPosition;
    do {
      newFoodPosition = {
        x: Math.floor(Math.random() * gridSize),
        y: Math.floor(Math.random() * gridSize),
      };
    } while (
      snakeBody.some(
        (segment) =>
          segment.x === newFoodPosition.x && segment.y === newFoodPosition.y
      )
    );
    return newFoodPosition;
  };

  useEffect(() => {
    setFood(generateFoodPosition(snake));
  }, []);

  // Fonctions de contrôle
  const startGame = () => {
    setSnake([{ x: 10, y: 10 }]);
    setDirection({ x: 0, y: -1 });
    setFood(generateFoodPosition([{ x: 10, y: 10 }]));
    setGameOver(false);
    setIsPlaying(true);
    setScore(0);
  };

  const stopGame = () => {
    setIsPlaying(false);
  };

  const resumeGame = () => {
    if (!gameOver) setIsPlaying(true);
  };

  const resetGame = () => {
    startGame();
  };

  return (
    <div className="relative flex flex-col items-center p-4">
      {/* Contrôles du jeu */}
      <div className="controls flex space-x-4 mb-4">
        <button
          onClick={startGame}
          className="px-4 py-2 bg-green-500 text-white rounded"
          aria-label="Démarrer le jeu"
        >
          <FaPlay />
        </button>
        <button
          onClick={stopGame}
          className="px-4 py-2 bg-red-500 text-white rounded"
          aria-label="Arrêter le jeu"
        >
          <FaPause />
        </button>
        <button
          onClick={resumeGame}
          className="px-4 py-2 bg-yellow-500 text-white rounded"
          aria-label="Reprendre le jeu"
        >
          <FaForward />
        </button>
        <button
          onClick={resetGame}
          className="px-4 py-2 bg-blue-500 text-white rounded"
          aria-label="Réinitialiser le jeu"
        >
          <FaRedo />
        </button>
      </div>

      {/* Score */}
      <div className="score flex items-center text-xl text-white mb-4 bg-gray-800 p-3 rounded-full shadow-lg">
        <FaTrophy className="text-yellow-400 mr-2" size={24} />
        Score : {score} | Meilleur : {highScore}
      </div>

      {/* Plateau de jeu */}
      <div
        ref={boardRef}
        className="game-board mx-auto relative bg-gradient-to-br from-gray-800 to-black"
        style={{
          width: gridSize * tileSize,
          height: gridSize * tileSize,
          position: 'relative',
          overflow: 'hidden',
        }}
      >
        {snake.map((segment, index) => (
          <div
            key={index}
            className="snake-segment absolute bg-green-400 transition-all duration-150"
            style={{
              left: `${segment.x * tileSize}px`,
              top: `${segment.y * tileSize}px`,
              width: `${tileSize}px`,
              height: `${tileSize}px`,
            }}
          ></div>
        ))}
        <div
          className="food absolute bg-red-500 rounded-full transition-all duration-150"
          style={{
            left: `${food.x * tileSize}px`,
            top: `${food.y * tileSize}px`,
            width: `${tileSize}px`,
            height: `${tileSize}px`,
          }}
        ></div>
        {gameOver && (
          <div className="overlay absolute inset-0 bg-black bg-opacity-50 flex items-center justify-center">
            <div className="text-white text-3xl">Game Over</div>
          </div>
        )}
      </div>

      {/* Contrôles directionnels */}
      <div className="direction-controls mt-8">
        <div className="relative w-40 h-40">
          {/* Cercle central avec pointer-events-none */}
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <FaRegCircle size={32} className="text-gray-600" />
          </div>

          {/* Flèche Haut */}
          <button
            onClick={() => handleDirectionChange({ x: 0, y: -1 })}
            className="absolute top-0 left-1/2 transform -translate-x-1/2 p-4 bg-gray-700 text-white rounded-full shadow-lg hover:bg-gray-600 focus:outline-none focus:ring-2 focus:ring-gray-500 active:scale-90 transition-transform"
            aria-label="Haut"
          >
            <FaArrowUp size={24} />
          </button>
          {/* Flèche Bas */}
          <button
            onClick={() => handleDirectionChange({ x: 0, y: 1 })}
            className="absolute bottom-0 left-1/2 transform -translate-x-1/2 p-4 bg-gray-700 text-white rounded-full shadow-lg hover:bg-gray-600 focus:outline-none focus:ring-2 focus:ring-gray-500 active:scale-90 transition-transform"
            aria-label="Bas"
          >
            <FaArrowDown size={24} />
          </button>
          {/* Flèche Gauche */}
          <button
            onClick={() => handleDirectionChange({ x: -1, y: 0 })}
            className="absolute left-0 top-1/2 transform -translate-y-1/2 p-4 bg-gray-700 text-white rounded-full shadow-lg hover:bg-gray-600 focus:outline-none focus:ring-2 focus:ring-gray-500 active:scale-90 transition-transform"
            aria-label="Gauche"
          >
            <FaArrowLeft size={24} />
          </button>
          {/* Flèche Droite */}
          <button
            onClick={() => handleDirectionChange({ x: 1, y: 0 })}
            className="absolute right-0 top-1/2 transform -translate-y-1/2 p-4 bg-gray-700 text-white rounded-full shadow-lg hover:bg-gray-600 focus:outline-none focus:ring-2 focus:ring-gray-500 active:scale-90 transition-transform"
            aria-label="Droite"
          >
            <FaArrowRight size={24} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default SnakeGame;
