import React from 'react';
import { useTranslation } from 'react-i18next';

const Testimonials = () => {
  const { t } = useTranslation();

  const testimonials = [
    {
      id: 1,
      name: t('testimonials.testimonial1.name'),
      feedback: t('testimonials.testimonial1.feedback'),
    },
    {
      id: 2,
      name: t('testimonials.testimonial2.name'),
      feedback: t('testimonials.testimonial2.feedback'),
    },
  ];

  return (
    <div className="w-full min-h-screen flex justify-center items-center bg-gradient-to-r from-blue-900 to-gray-700 p-32">
      <div className="max-w-screen-lg mx-auto px-8 bg-gray-800 bg-opacity-80 p-8 rounded-lg shadow-2xl backdrop-blur-md">
        <h2 className="text-5xl font-extrabold mb-12 text-center text-white">
          {t('testimonials.title')}
        </h2>
        <div className="grid gap-8 sm:grid-cols-1 md:grid-cols-2">
          {testimonials.map(({ id, name, feedback }) => (
            <div key={id} className="bg-gray-700 bg-opacity-70 p-6 rounded-lg shadow-lg transform hover:-translate-y-2 hover:bg-opacity-80 transition duration-300 ease-in-out">
              <p className="text-xl font-light mb-4 text-gray-300 leading-relaxed">"{feedback}"</p>
              <h3 className="text-2xl font-bold text-gray-100">{name}</h3>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Testimonials;
