import React from 'react';
import { useTranslation } from 'react-i18next';
import { FaGraduationCap } from 'react-icons/fa';
import { motion } from 'framer-motion';

interface Formation {
  time: string;
  degree: string;
  school?: string;
  description?: string;
}

interface FormationCardProps {
  formation: Formation;
}

const FormationCard: React.FC<FormationCardProps> = React.memo(({ formation }) => (
  <motion.li
    className="relative mb-12 pl-10"
    initial={{ opacity: 0, y: 50 }}
    whileInView={{ opacity: 1, y: 0 }}
    transition={{ duration: 0.6, ease: 'easeOut' }}
    viewport={{ once: true }}
  >
    {/* Icône Timeline */}
    <span
      className="absolute -left-6 top-1/2 z-10 flex h-12 w-12 -translate-y-1/2 transform items-center justify-center rounded-full bg-gradient-to-br from-gray-700 to-gray-500 text-white shadow-lg transition-transform duration-300 hover:scale-110"
      aria-hidden="true"
    >
      <FaGraduationCap size={24} />
    </span>

    {/* Contenu de la carte */}
    <div className="relative rounded-2xl bg-white bg-opacity-60 backdrop-filter backdrop-blur-lg p-6 shadow-xl transition-all duration-300 hover:bg-opacity-70 dark:bg-gray-800 dark:bg-opacity-80">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between">
        <time className="text-sm font-semibold text-gray-600 dark:text-gray-400">
          {formation.time}
        </time>
        <div className="mt-2 text-right sm:mt-0">
          <h3 className="text-xl font-bold text-gray-900 dark:text-gray-100">
            {formation.degree}
          </h3>
          {formation.school && (
            <h4 className="mt-1 text-lg font-medium text-gray-500 dark:text-gray-400">
              {formation.school}
            </h4>
          )}
        </div>
      </div>
      {formation.description && (
        <p className="mt-4 text-base text-gray-700 dark:text-gray-300">
          {formation.description}
        </p>
      )}
    </div>
  </motion.li>
));

const Timeline: React.FC = () => {
  const { t } = useTranslation();

  const formations: Formation[] = [
    {
      time: t('experience.formation1.time'),
      degree: t('experience.formation1.degree'),
      school: t('experience.formation1.school'),
      description: t('experience.formation1.description'),
    },
    {
      time: t('experience.formation2.time'),
      degree: t('experience.formation2.degree'),
      school: t('experience.formation2.school'),
      description: t('experience.formation2.description'),
    },
    {
      time: t('experience.formation3.time'),
      degree: t('experience.formation3.degree'),
      description: t('experience.formation3.description'),
    },
    {
      time: t('experience.formation4.time'),
      degree: t('experience.formation4.degree'),
    },
  ];

  return (
    <div className="mx-auto w-full max-w-4xl px-6 py-12 bg-gray-50 bg-opacity-80 shadow-2xl rounded-3xl dark:bg-gray-900">
      <div className="text-center mb-12">
        <h2 className="text-4xl font-extrabold text-gray-800 dark:text-gray-100">
          {t('experience.title')}
        </h2>
      </div>
      <ol className="relative border-l-4 border-gray-200 dark:border-gray-700">
        {formations.map((formation, index) => (
          <FormationCard key={index} formation={formation} />
        ))}
      </ol>
    </div>
  );
};

export default Timeline;
