import React from 'react';
import ContactForm from '../components/ContactForm';
import { FaEnvelope } from 'react-icons/fa';
import { useTranslation } from 'react-i18next';

const Contact = () => {
  const { t } = useTranslation();

  return (
    <section className="relative w-full min-h-screen bg-gradient-to-b from-gray-900 to-black text-white py-32 px-8 flex items-center justify-center">
      {/* Arrière-plan avec effet visuel moderne */}
      <div
        className="absolute inset-0 bg-fixed bg-center bg-cover opacity-20"
        style={{ backgroundImage: 'url(/path/to/your/background-image.jpg)' }}
      ></div>

      {/* Contenu principal avec effet de verre (glassmorphism) */}
      <div className="relative w-full max-w-screen-md mx-auto bg-white bg-opacity-5 backdrop-filter backdrop-blur-lg rounded-xl shadow-xl p-8">
        {/* Titre déplacé ici */}
        <div className="text-center my-8">
          <h2 className="text-4xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-purple-400 to-blue-500 pb-4 mb-6">
            {t('contact.title')}
          </h2>
        </div>

        <div className="flex justify-center mb-8">
          <FaEnvelope className="text-6xl text-gray-300" />
        </div>

        <ContactForm />
      </div>
    </section>
  );
};

export default Contact;
